/**
 * Final Parse Kodu: N8N JS ortamına %100 uyumlu (harici kütüphanesiz) ve NULL değeri döndürmeyen versiyon.
 * * @returns {array} - Düzleştirilmiş ve NULL değeri içermeyen veriyi içeren çıktı dizisi.
 */

const items = [];
for (const item of $input.all()) {

    // Girdi verisine güvenli erişim
    const rawMessage = item.json.raw_message || ($('WhatsApp Trigger').length > 0 && $('WhatsApp Trigger').first().json.messages[0].text.body) || ''; 
    const lowerCaseMessage = rawMessage.toLowerCase().trim();

    // --- TEMEL DEĞİŞKEN TANIMLARI ---
    let targetDate = new Date();
    const now = new Date();

    let parsedDateTime = null; // ISO 8601 (LLM/DB)
    let appointmentDate = null; // GG-AA-YYYY (Sheet)
    let appointmentTime = null; // SS:DD (Sheet)
    let serviceType = 'Belirtilmedi / Diğer'; 
    let fullName = null; // Çekilen İsim Değeri

    let hour = null;
    let minute = '00';
    let isPM = false;

    // --- YARDIMCI İSİM FİLTRESİ ---
    // Türkçe karakterleri desteklemek için özel bir filtre oluşturulur (Unicode RegEx kullanmadan).
    const turkishChars = "a-zıİçÇşŞüÜöÖğĞ";

    // --- 1. TAM İSİM TESPİTİ (SADELEŞTİRİLMİŞ) ---

    function extractFullName(message) {
        // İsim tespiti için mesajı normalize et (Kelime başları büyük harfe çevrilir)
        const capitalizedMessage = message.split(' ').map(word => {
            if (word.length > 0) {
                // Kelimeyi büyük harfle başlat
                return word.charAt(0).toUpperCase() + word.slice(1);
            }
            return word;
        }).join(' ');

        // 1. Anahtar Kelime Sonrası Yakalama (Örn: "adım Ayşe Yılmaz")
        // (\w\s) yerine, Türkçeye uygun harf setini içeren ve basit olanı kullanırız.
        const nameKeywordsRegex = new RegExp(`(?:benim adım|adım|ismim|ben)\\s+([${turkishChars}\\s]{2,40})`, 'i'); 
        let nameMatch = capitalizedMessage.match(nameKeywordsRegex);

        if (nameMatch && nameMatch[1]) {
            return nameMatch[1].trim().split(/\s+/).slice(0, 3).join(' ');
        }

        // 2. Randevuya Bağlı İsim Yakalama (Örn: "Ahmet Arif UYBADIN adına randevu")
        const specificNameRegex = new RegExp(`adına\\s+([${turkishChars}\\s]{2,40}) randevu`, 'i'); 
        nameMatch = capitalizedMessage.match(specificNameRegex);

        if (nameMatch && nameMatch[1]) {
             const capturedName = nameMatch[1].trim();
             if (capturedName.split(/\s+/).length >= 2) { 
                return capturedName;
             }
        }

        // 3. Cümle Başı İsim Yakalama (Randevu kelimesinden önce gelen 1-3 kelime)
        const sentenceStartRegex = new RegExp(`^([${turkishChars}\\s]{2,30}) randevu`, 'i');
        nameMatch = capitalizedMessage.match(sentenceStartRegex);

        if (nameMatch && nameMatch[1]) {
            return nameMatch[1].trim();
        }

        return null;
    }

    fullName = extractFullName(rawMessage);

    // --- 2. HİZMET TÜRÜ TESPİTİ ---
    const serviceKeywords = {
        "saç kesimi": ["kesim", "saç"],
        "boya/röfle": ["boya", "röfle", "ombre"],
        "manikür/pedikür": ["manikür", "pedikür", "tırnak"],
        "fön/şekillendirme": ["fön", "şekillendirme", "topuz"]
    };

    for (const type in serviceKeywords) {
        for (const keyword of serviceKeywords[type]) {
            if (lowerCaseMessage.includes(keyword)) {
                serviceType = type;
                break; 
            }
        }
        if (serviceType !== 'Belirtilmedi / Diğer') {
            break;
        }
    }

    // --- 3. GÜN TESPİTİ ---
    let dayFound = false;

    if (lowerCaseMessage.includes("yarın") || lowerCaseMessage.includes("yarin")) {
        targetDate.setDate(targetDate.getDate() + 1);
        dayFound = true;
    } 

    const dayNames = { "pazartesi": 1, "salı": 2, "çarşamba": 3, "perşembe": 4, "cuma": 5, "cumartesi": 6, "pazar": 0 };
    const todayDay = now.getDay();

    if (!dayFound) {
        for (const name in dayNames) {
            if (lowerCaseMessage.includes(name)) {
                let targetDay = dayNames[name];
                let diff = targetDay - todayDay;

                // Bugün Cumartesi (6) ise ve Salı (2) isteniyorsa: 2 - 6 = -4. Yeni hafta: -4 + 7 = 3 gün sonra.
                if (diff <= 0) { diff += 7; } 
                if (lowerCaseMessage.includes("gelecek hafta")) { diff += 7; }

                targetDate.setDate(now.getDate() + diff); 
                dayFound = true;
                break;
            }
        }
    }

    // --- 4. SAAT TESPİTİ VE DÖNÜŞÜMÜ ---

    const timeRegex = /(?:\bsaat\s*)?(\d{1,2})(?:[:\s\.](\d{2}))?/g;
    let matches = timeRegex.exec(lowerCaseMessage);

    if (matches) {
        hour = parseInt(matches[1]);
        minute = matches[2] || '00';

        if (hour < 12) { 
            if (lowerCaseMessage.includes("akşam") || lowerCaseMessage.includes("ogle") || lowerCaseMessage.includes("öğle") || lowerCaseMessage.includes("öğleden sonra")) {
                isPM = true;
            }
        }
    }

    if (hour !== null) {
        if (isPM && hour < 12) { hour += 12; } 
        else if (!isPM && hour === 12) { hour = 0; }
    }

    // --- 5. BİRLEŞTİRME VE ÇIKTI FORMATLAMA (NULL GARANTİSİ) ---

    // A. SAAT VE GÜN VARSA (TAM BİLGİ VAR)
    if (hour !== null && (dayFound || lowerCaseMessage.includes("bugün"))) {

        let finalDate = new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate());

        finalDate.setHours(hour);
        finalDate.setMinutes(parseInt(minute));

        parsedDateTime = finalDate.toISOString();

        const day = finalDate.getDate().toString().padStart(2, '0');
        const month = (finalDate.getMonth() + 1).toString().padStart(2, '0');
        const year = finalDate.getFullYear();
        appointmentDate = `${day}-${month}-${year}`;

        const hoursFormatted = finalDate.getHours().toString().padStart(2, '0');
        const minutesFormatted = finalDate.getMinutes().toString().padStart(2, '0');
        appointmentTime = `${hoursFormatted}:${minutesFormatted}`;

    } 
    // B. SADECE GÜN VARSA (Saat eksik) - Randevu İptali/Listeleme için Tarihi yine de döndür.
    else if (dayFound) {
        // Tarih formatını hesapla (Saati sıfırlar)
        const day = targetDate.getDate().toString().padStart(2, '0');
        const month = (targetDate.getMonth() + 1).toString().padStart(2, '0');
        const year = targetDate.getFullYear();
        appointmentDate = `${day}-${month}-${year}`;

        // parsedDateTime ve appointmentTime null kalır.
    }

    // --- 6. NİHAİ ÇIKTIYI OLUŞTURMA (NULL'U STRING'E ÇEVİRME GARANTİSİ) ---
    items.push({
        json: {
            // Önceki girdiler korunur
            ...item.json,
            raw_message: rawMessage,

            // NULL'ları string'e çevirir
            parsed_date: parsedDateTime === null ? "null" : parsedDateTime,
            appointment_date: appointmentDate === null ? "null" : appointmentDate,
            appointment_time: appointmentTime === null ? "Saat Eksik" : appointmentTime,

            // Diğerleri
            service_type: serviceType,
            full_name: fullName === null ? "null" : fullName 
        },
    });
}

// Sonuç olarak, nesnelerden oluşan bir dizi (array) döndürülür
return items;

/**
 * Input Normalizer
 * WhatsApp veya Webhook'tan gelen mesajı tek formata çevirir.
 * Çıktı:
 * raw_message
 * phone_number
 * user_name
 * contains_time_info
 * is_reschedule_intent
 * is_cancel_intent
 * is_availability_query
 */

const items = [];
const input = $input.first()?.json || {};

let rawMessage = '';
let phoneNumber = '';
let userName = '';
let errorStatus = false;

try {
  // 1) WhatsApp Cloud API formatı
  rawMessage =
    input.messages?.[0]?.text?.body ||
    input.body?.messages?.[0]?.text?.body ||

    // 2) Webhook test formatı
    input.message ||
    input.body?.message ||
    input.text ||
    input.body?.text ||
    '';

  phoneNumber =
    input.contacts?.[0]?.wa_id ||
    input.body?.contacts?.[0]?.wa_id ||
    input.phone ||
    input.body?.phone ||
    '';

  userName =
    input.contacts?.[0]?.profile?.name ||
    input.body?.contacts?.[0]?.profile?.name ||
    input.name ||
    input.body?.name ||
    '';

  if (!rawMessage || typeof rawMessage !== 'string') {
    throw new Error('Mesaj içeriği bulunamadı.');
  }

  const lower = rawMessage.toLowerCase().trim();

  const timeKeywords = [
    'yarın', 'yarin', 'bugün', 'bugun',
    'pazartesi', 'salı', 'sali', 'çarşamba', 'carsamba',
    'perşembe', 'persembe', 'cuma', 'cumartesi', 'pazar',
    'hafta', 'saat', 'randevu', 'gün', 'gun',
    'ne zaman', 'saç', 'sac', 'kesim'
  ];

  const rescheduleKeywords = [
    'düzenle', 'duzenle', 'değiştir', 'degistir',
    'kaydır', 'kaydir', 'ertele', 'yeni zaman',
    'başka bir gün', 'baska bir gun'
  ];

  const cancelKeywords = [
    'iptal', 'vazgeç', 'vazgectim', 'gelemeyeceğim',
    'gelemeyecegim', 'sil'
  ];

  const availabilityKeywords = [
    'boş saat', 'bos saat', 'müsait', 'musait',
    'uygun saat', 'hangi saat', 'saatler',
    'boşluk', 'bosluk'
  ];

  const numericTimeRegex = /\b\d{1,2}([:.]\d{2})?\b/;

  const containsTimeInfo =
    numericTimeRegex.test(lower) ||
    timeKeywords.some(k => lower.includes(k));

  const isRescheduleIntent =
    rescheduleKeywords.some(k => lower.includes(k));

  const isCancelIntent =
    cancelKeywords.some(k => lower.includes(k));

  const isAvailabilityQuery =
    availabilityKeywords.some(k => lower.includes(k)) ||
    (
      containsTimeInfo &&
      !isCancelIntent &&
      !isRescheduleIntent &&
      !numericTimeRegex.test(lower)
    );

  items.push({
    json: {
      ...input,
      raw_message: rawMessage,
      phone_number: phoneNumber,
      user_name: userName,
      contains_time_info: containsTimeInfo,
      is_reschedule_intent: isRescheduleIntent,
      is_cancel_intent: isCancelIntent,
      is_availability_query: isAvailabilityQuery,
      error_status: false
    }
  });

} catch (error) {
  items.push({
    json: {
      ...input,
      raw_message: rawMessage || '',
      phone_number: phoneNumber || '',
      user_name: userName || '',
      contains_time_info: false,
      is_reschedule_intent: false,
      is_cancel_intent: false,
      is_availability_query: false,
      error_status: true,
      error_message: error.message
    }
  });
}

return items;

/**
 * NİHAİ UYUMLULUK VE ÇÖZÜMLEME KODU (Yıl İyileştirmeli Sürüm)
 * Bu kod, geçmiş yıldan gelen mutlak tarihleri otomatik olarak güncel yıla çeker (Future Date Correction) 
 * ve tüm Türkçe/göreceli zamanları hesaplar.
 *
 * @returns {array} - Tüm ISO, net tarih ve hesaplanmış zamanları içeren çıktı dizisi.
 */

const items = $input.all();
const outputItems = []; 
const now = new Date();

// --- SABİT İŞ MANTIĞI: SÜRELER VE YARDIMCI FONKSİYONLAR ---
const SERVICE_DURATIONS = {
    "Kişisel bakım": 150, "Saç Kesimi": 60, "Boya/Röfle": 150, "Manikür/Pedikür": 90, 
    "Fön/Şekillendirme": 30, "Genel bakım": 150, "saç kesim": 60, "Belirtilmedi / Diğer": 60 
};

// YARDIMCI FONKSİYON 1: Türkçe Gün Adı/İfadesinden Net Tarihi Bulan Fonksiyon
function resolveRelativeDate(dateString, timeString) {
    const lowerDate = String(dateString || '').toLowerCase().trim();
    const lowerTime = String(timeString || '').toLowerCase().trim();

    if (!lowerDate || lowerDate === 'null') return null;

    let targetDate = new Date(now.getFullYear(), now.getMonth(), now.getDate()); 
    let dateResolved = false;

    // YENİ KRİTİK ADIM: Mutlak Tarih Formatını Kontrol Etme
    const absoluteDateRegex = /(\d{4}[-/]\d{1,2}[-/]\d{1,2})|(\d{1,2}[-/]\d{1,2}[-/]\d{4})/;
    const absoluteMatch = lowerDate.match(absoluteDateRegex);

    if (absoluteMatch) {
        try {
            let parsedDate = new Date(absoluteMatch[0]); 
            if (!isNaN(parsedDate.getTime())) {

                // --- KRİTİK DÜZELTME: GEÇMİŞ YIL KONTROLÜ (2024 -> 2025) ---
                const currentYear = now.getFullYear();
                if (parsedDate.getFullYear() < currentYear) {
                    parsedDate.setFullYear(currentYear);
                }

                targetDate = parsedDate; 
                dateResolved = true;
            }
        } catch (e) {
        }
    }

    // 1. Gün Tespiti (SADECE Mutlak Tarih Bulunamazsa Çalışır)
    if (!dateResolved) {
        if (lowerDate.includes("yarın") || lowerDate.includes("yarin")) {
            targetDate.setDate(targetDate.getDate() + 1);
        } else {
            const dayNames = { "pazartesi": 1, "salı": 2, "çarşamba": 3, "perşembe": 4, "cuma": 5, "cumartesi": 6, "pazar": 0 };
            const todayDay = targetDate.getDay();

            for (const name in dayNames) {
                if (lowerDate.includes(name)) {
                    let targetDay = dayNames[name];
                    let diff = targetDay - todayDay;

                    if (diff <= 0) diff += 7; 

                    targetDate.setDate(targetDate.getDate() + diff);
                    break;
                }
            }
        }
    }

    // 2. Saat Tespiti
    let hour = 10; 
    let minute = 0;

    const numericTimeRegex = /(\d{1,2})(?::(\d{2}))?/;
    let timeMatch = lowerTime.match(numericTimeRegex);

    if (timeMatch) {
        hour = parseInt(timeMatch[1]);
        minute = parseInt(timeMatch[2] || 0);
    }

    if (lowerTime.includes("öğleden sonra") || lowerTime.includes("öğle") || lowerTime.includes("akşam")) {
        if (hour < 12) hour += 12;
    }

    targetDate.setHours(hour);
    targetDate.setMinutes(minute);

    return targetDate; 
}

// YARDIMCI FONKSİYON 2: Bitiş Zamanını Hesaplar
function calculateEndTimes(startDateObj, serviceType) {
    if (!startDateObj) return { start_iso: 'null', end_iso: 'null', startDateObj: null };

    const durationMinutes = SERVICE_DURATIONS[serviceType] || SERVICE_DURATIONS["Belirtilmedi / Diğer"];

    if (!isNaN(startDateObj.getTime())) {
        let endDateObj = new Date(startDateObj.getTime() + durationMinutes * 60000); 
        return {
            start_iso: startDateObj.toISOString(),
            end_iso: endDateObj.toISOString(),
            startDateObj: startDateObj 
        };
    }
    return { start_iso: 'null', end_iso: 'null', startDateObj: null };
}

// YARDIMCI FONKSİYON 3: Regex ile Satır Bazında Değer Çeker
const KEY_MAP = {
    "İsim": "full_name", "isim": "full_name", "Randevu servis tipi": "service_type", 
    "randevu servis tipi": "service_type", "Randevu tarihi": "appointment_date", "randevu tarihi": "appointment_date",
    "Randevu saati": "appointment_time", "randevu saati": "appointment_time", "Telefon numarası": "user_id", 
    "telefon numarası": "user_id", "randevuDuzenleme": "is_reschedule_intent", "yeniRandevuTarihi": "new_appointment_date_raw", 
    "yeniRandevuSaati": "new_appointment_time_raw", "yeniRandevuServisTalebi": "new_service_type", "operation_type": "operation_type"
};
const regex = /"\s*([^"]+)\s*"\s*:\s*["']?([^"']+)["']?/i; 

for (const item of items) {
    let finalData = {};
    let errorDetected = false;

    try {
        let llmOutputString = item.json.message?.content || item.json.content;
        if (!llmOutputString) throw new Error("Çıktı dizesi ('content' alanı) boş.");

        // --- ADIM 1: ÇOKLU JSON ÇIKTISINDAN VERİLERİ ÇEKME ---
        const lines = llmOutputString.split('\n');

        for (const line of lines) {
            const trimmedLine = line.trim();
            if (trimmedLine.includes(':')) {

                 const match = trimmedLine.match(regex);

                 if (match && match.length >= 3) {
                    const key = match[1].trim();
                    const value = match[2].trim();

                    const mappedKey = KEY_MAP[key] || key.toLowerCase().replace(/\s/g, '_');
                    finalData[mappedKey] = value;
                 }
            }
        }

        // --- ADIM 2: TARİH/SAAT ÇÖZÜMLEME VE HESAPLAMA ---
        const appointmentDate = finalData.appointment_date;
        const appointmentTime = finalData.appointment_time;
        const serviceType = finalData.service_type;

        const startDateObj = resolveRelativeDate(appointmentDate, appointmentTime);
        const isoTimes = calculateEndTimes(startDateObj, serviceType);

        const newAppointmentDateRaw = finalData.new_appointment_date_raw;
        const newAppointmentTimeRaw = finalData.new_appointment_time_raw;
        const newServiceType = finalData.new_service_type || serviceType;

        const newStartDateObj = resolveRelativeDate(newAppointmentDateRaw, newAppointmentTimeRaw);
        const newIsoTimes = calculateEndTimes(newStartDateObj, newServiceType);

        finalData.start_datetime_iso = isoTimes.start_iso;
        finalData.end_datetime_iso = isoTimes.end_iso;
        finalData.reschedule_start_iso = newIsoTimes.start_iso;
        finalData.reschedule_end_iso = newIsoTimes.end_iso;
        finalData.raw_message = item.json.raw_message || 'null';

        const pad = (num) => String(num).padStart(2, '0');

        if (isoTimes.startDateObj) {
            const date = isoTimes.startDateObj;
            finalData.appointment_date_net = `${pad(date.getDate())}-${pad(date.getMonth() + 1)}-${date.getFullYear()}`;
            finalData.appointment_time_net = `${pad(date.getHours())}:${pad(date.getMinutes())}`;
        } else {
            finalData.appointment_date_net = 'null';
            finalData.appointment_time_net = 'null';
        }

        if (newIsoTimes.startDateObj) {
            const date = newIsoTimes.startDateObj;
            finalData.reschedule_date_net = `${pad(date.getDate())}-${pad(date.getMonth() + 1)}-${date.getFullYear()}`;
            finalData.reschedule_time_net = `${pad(date.getHours())}:${pad(date.getMinutes())}`;
        } else {
            finalData.reschedule_date_net = 'null';
            finalData.reschedule_time_net = 'null';
        }

    } catch (error) {
        errorDetected = true;
        finalData = { 
            full_name: 'HATA_AKIŞ_KOPUK', 
            operation_type: 'Hata Bildirimi',
            error_details: error.message 
        };
        console.error("KRİTİK HATA: Hesaplama/Parse Başarısız:", error.message);
    }

    outputItems.push({
        json: {
            ...item.json, 

            full_name: finalData.full_name || 'Bilinmiyor',
            service_type: finalData.service_type || 'Belirtilmedi / Diğer',
            appointment_date: finalData.appointment_date || 'null',
            appointment_time: finalData.appointment_time || 'Saat Eksik',
            start_datetime_iso: finalData.start_datetime_iso || 'null',
            end_datetime_iso: finalData.end_datetime_iso || 'null',

            reschedule_start_iso: finalData.reschedule_start_iso || 'null',
            reschedule_end_iso: finalData.reschedule_end_iso || 'null',
            new_service_type: finalData.new_service_type || finalData.service_type || 'null',
            reschedule_date_net: finalData.reschedule_date_net || 'null',
            reschedule_time_net: finalData.reschedule_time_net || 'null',

            appointment_date_net: finalData.appointment_date_net || 'null',
            appointment_time_net: finalData.appointment_time_net || 'null',

            user_id: finalData.user_id || 'null',
            operation_type: finalData.operation_type || 'Randevu Oluşturma', 
            raw_message: finalData.raw_message,

            parsing_success: !errorDetected
        }
    });
}

return outputItems;

/**
 * İPTAL ONAY ÇIKTISI PARSE KODU (NİHAİ VERSİYON)
 * Kod, 'event_id' veya 'eventID' varyasyonlarını yakalar ve mesajı temizler.
 *
 * @returns {array} - Temizlenmiş mesaj ve Event ID içeren çıktı.
 */

const items = $input.all();
const outputItems = [];

for (const item of items) {
    // Ham çıktıyı al (örneğin: item.json.output)
    let rawOutput = item.json.output || item.json.message?.content || String(item.json); 

    // Kaçış ve satır sonu karakterlerini temizle: \n, \t ve çift kaçış işaretlerini temizler
    let cleanOutput = rawOutput.replace(/\\n/g, ' ').replace(/\\"/g, '"').replace(/\\/g, '').trim();

    // --- 1. EVENT ID'yi Çekme (KRİTİK DÜZELTME) ---
    // Regex Açıklaması: "event", ardından isteğe bağlı bir alt çizgi (_), ardından "id" arar.
    // 'i' (case-insensitive) bayrağı sayesinde 'eventID' veya 'eventid' gibi varyasyonlar da yakalanır.
    const eventIdRegex = /"event[_]?id"\s*:\s*"([^"]+)"/i;
    const eventIdMatch = cleanOutput.match(eventIdRegex);

    const eventId = eventIdMatch && eventIdMatch[1] ? eventIdMatch[1].trim() : 'NOT_FOUND';

    // --- 2. MESAJI ÇEKME ---
    // "message": "MESAJ METNİ" yapısını çeker.
    const messageRegex = /"message"\s*:\s*"([^"]*)"/; 
    const messageMatch = cleanOutput.match(messageRegex);

    let confirmationMessage = 'İşlem Başarılı: Mesaj metni çekilemedi.';

    if (messageMatch && messageMatch[1]) {
        // Tırnaklar arasındaki temiz metni al
        confirmationMessage = messageMatch[1].trim();
    } else {
        // Fallback: Eğer Regex başarısız olursa, ID'den önceki metni mesaj olarak al.
        const idIndex = cleanOutput.toLowerCase().indexOf('eventid');
        if (idIndex !== -1) {
             confirmationMessage = cleanOutput.substring(0, idIndex).replace(/\{|\}|"|message:|/g, '').trim();
        }
    }

    // Final çıktı objesini oluşturma
    outputItems.push({
        json: {
            ...item.json,
            final_confirmation_message: confirmationMessage,
            deleted_event_id: eventId,
            cancellation_success: eventId !== 'NOT_FOUND' 
        }
    });
}

return outputItems;

/**
 * AI Agent çıktısını güvenli JSON'a çevirir.
 */

const outputItems = [];

for (const item of $input.all()) {
  const raw =
    item.json.output ||
    item.json.text ||
    item.json.message?.content ||
    item.json.content ||
    '';

  let parsed = {};

  try {
    let clean = String(raw).trim();

    // Markdown code block geldiyse temizle
    clean = clean
      .replace(/^```json/i, '')
      .replace(/^```/i, '')
      .replace(/```$/i, '')
      .trim();

    const firstBrace = clean.indexOf('{');
    const lastBrace = clean.lastIndexOf('}');

    if (firstBrace !== -1 && lastBrace !== -1) {
      clean = clean.slice(firstBrace, lastBrace + 1);
    }

    parsed = JSON.parse(clean);
  } catch (error) {
    parsed = {
      operation_type: 'missing_info',
      full_name: null,
      phone_number: item.json.phone_number || null,
      service_type: 'Belirtilmedi / Diğer',
      appointment_date: null,
      appointment_time: null,
      new_appointment_date: null,
      new_appointment_time: null,
      new_service_type: null,
      customer_message: 'Mesajınızı tam anlayamadım. Randevu almak istediğiniz gün ve saati yazar mısınız?',
      parse_error: error.message,
      raw_ai_output: raw
    };
  }

  outputItems.push({
    json: {
      ...item.json,
      ...parsed,
      phone_number: parsed.phone_number || item.json.phone_number || item.json.phone || $('Code in JavaScript1').first().json.phone_number || null,
full_name: parsed.full_name || item.json.full_name || item.json.user_name || $('Code in JavaScript1').first().json.user_name || null,
      raw_ai_output: raw,
      ai_parse_success: !parsed.parse_error
    }
  });
}

return outputItems;

/**
 * Türkçe tarih/saat ifadelerini ISO formatına çevirir.
 * Ayrıca Google Calendar sorgusu için gün başlangıç/bitiş aralığı üretir.
 */

const outputItems = [];

const SERVICE_DURATIONS = {
  'Saç Kesimi': 60,
  'Boya/Röfle': 150,
  'Manikür/Pedikür': 90,
  'Fön/Şekillendirme': 30,
  'Belirtilmedi / Diğer': 60
};

function pad(n) {
  return String(n).padStart(2, '0');
}

function normalizeTurkish(str) {
  return String(str || '')
    .toLowerCase()
    .replace(/ı/g, 'i')
    .replace(/ğ/g, 'g')
    .replace(/ü/g, 'u')
    .replace(/ş/g, 's')
    .replace(/ö/g, 'o')
    .replace(/ç/g, 'c')
    .trim();
}

function resolveDate(dateText) {
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const text = normalizeTurkish(dateText);

  let target = new Date(today);

  if (!text || text === 'null') {
    return target;
  }

  if (text.includes('bugun')) {
    return target;
  }

  if (text.includes('yarin')) {
    target.setDate(target.getDate() + 1);
    return target;
  }

  const afterDaysMatch = text.match(/(\d+)\s*gun\s*sonra/);
  if (afterDaysMatch) {
    target.setDate(target.getDate() + Number(afterDaysMatch[1]));
    return target;
  }

  const dayMap = {
    'pazar': 0,
    'pazartesi': 1,
    'sali': 2,
    'carsamba': 3,
    'persembe': 4,
    'cuma': 5,
    'cumartesi': 6
  };

  for (const [name, dayNumber] of Object.entries(dayMap)) {
    if (text.includes(name)) {
      const currentDay = today.getDay();
      let diff = dayNumber - currentDay;
      if (diff <= 0) diff += 7;
      target.setDate(target.getDate() + diff);
      return target;
    }
  }

  // dd-mm-yyyy veya dd/mm/yyyy
  const dmy = text.match(/(\d{1,2})[-/.](\d{1,2})(?:[-/.](\d{4}))?/);
  if (dmy) {
    const day = Number(dmy[1]);
    const month = Number(dmy[2]) - 1;
    const year = dmy[3] ? Number(dmy[3]) : now.getFullYear();
    return new Date(year, month, day);
  }

  return target;
}

function resolveTime(timeText) {
  const text = normalizeTurkish(timeText);

  if (!text || text === 'null') {
    return null;
  }

  const match = text.match(/(\d{1,2})(?::|\.|\s)?(\d{2})?/);
  if (!match) return null;

  let hour = Number(match[1]);
  let minute = match[2] ? Number(match[2]) : 0;

  if (
    (text.includes('aksam') || text.includes('ogleden sonra') || text.includes('ogle')) &&
    hour < 12
  ) {
    hour += 12;
  }

  return { hour, minute };
}

for (const item of $input.all()) {
  const j = item.json;

  const operationType = j.operation_type || 'availability_query';
  const serviceType = j.service_type || 'Belirtilmedi / Diğer';
  const duration = SERVICE_DURATIONS[serviceType] || 60;

  const baseDate = resolveDate(j.appointment_date || 'bugün');
  const time = resolveTime(j.appointment_time);

  const dayStart = new Date(baseDate);
  dayStart.setHours(0, 0, 0, 0);

  const dayEnd = new Date(baseDate);
  dayEnd.setHours(23, 59, 59, 999);

  let startDateTime = null;
  let endDateTime = null;

  if (time) {
    startDateTime = new Date(baseDate);
    startDateTime.setHours(time.hour, time.minute, 0, 0);

    endDateTime = new Date(startDateTime.getTime() + duration * 60000);
  }

  outputItems.push({
    json: {
      ...j,

      service_duration_minutes: duration,

      query_date_net: `${pad(baseDate.getDate())}-${pad(baseDate.getMonth() + 1)}-${baseDate.getFullYear()}`,
      query_day_start_iso: dayStart.toISOString(),
      query_day_end_iso: dayEnd.toISOString(),

      appointment_date_net: `${pad(baseDate.getDate())}-${pad(baseDate.getMonth() + 1)}-${baseDate.getFullYear()}`,
      appointment_time_net: time ? `${pad(time.hour)}:${pad(time.minute)}` : null,

      start_datetime_iso: startDateTime ? startDateTime.toISOString() : null,
      end_datetime_iso: endDateTime ? endDateTime.toISOString() : null
    }
  });
}

return outputItems;

/**
 * Google Calendar eventlerini alır, çalışma saatlerinden doluları çıkarır.
 * Boş slotları üretir.
 */

const ctx = $('Resolve Date and Time').first().json;

const WORK_START = '09:00';
const WORK_END = '18:00';
const SLOT_MINUTES = Number(ctx.service_duration_minutes || 60);

// Mola varsa burayı sonra açarız
const LUNCH_START = null; // örnek: '13:00'
const LUNCH_END = null;   // örnek: '14:00'

function pad(n) {
  return String(n).padStart(2, '0');
}

function setTime(baseDate, hhmm) {
  const [h, m] = hhmm.split(':').map(Number);
  const d = new Date(baseDate);
  d.setHours(h, m, 0, 0);
  return d;
}

function overlaps(aStart, aEnd, bStart, bEnd) {
  return aStart < bEnd && aEnd > bStart;
}

const baseDate = new Date(ctx.query_day_start_iso);
const workStart = setTime(baseDate, WORK_START);
const workEnd = setTime(baseDate, WORK_END);

const now = new Date();

let effectiveStart = new Date(workStart);

// Bugünse geçmiş saatleri gösterme
if (
  now.getFullYear() === baseDate.getFullYear() &&
  now.getMonth() === baseDate.getMonth() &&
  now.getDate() === baseDate.getDate()
) {
  effectiveStart = new Date(Math.max(workStart.getTime(), now.getTime() + 30 * 60000));

  const minutes = effectiveStart.getMinutes();

  if (minutes > 0 && minutes <= 30) {
    effectiveStart.setMinutes(30, 0, 0);
  } else if (minutes > 30) {
    effectiveStart.setHours(effectiveStart.getHours() + 1, 0, 0, 0);
  }
}

const calendarItems = $input.all().map(i => i.json);

const busy = calendarItems.map(e => {
  const startRaw =
    e.start?.dateTime ||
    e.start?.date ||
    e.startDateTime ||
    e.start_date ||
    e.start_time;

  const endRaw =
    e.end?.dateTime ||
    e.end?.date ||
    e.endDateTime ||
    e.end_date ||
    e.end_time;

  return {
    start: new Date(startRaw),
    end: new Date(endRaw)
  };
}).filter(e => !isNaN(e.start.getTime()) && !isNaN(e.end.getTime()));

if (LUNCH_START && LUNCH_END) {
  busy.push({
    start: setTime(baseDate, LUNCH_START),
    end: setTime(baseDate, LUNCH_END)
  });
}

const slots = [];
let cursor = new Date(effectiveStart);

while (cursor < workEnd) {
  const slotStart = new Date(cursor);
  const slotEnd = new Date(slotStart.getTime() + SLOT_MINUTES * 60000);

  if (slotEnd <= workEnd) {
    const isBusy = busy.some(b => overlaps(slotStart, slotEnd, b.start, b.end));

    if (!isBusy) {
      slots.push({
        time: `${pad(slotStart.getHours())}:${pad(slotStart.getMinutes())}`,
        start_iso: slotStart.toISOString(),
        end_iso: slotEnd.toISOString()
      });
    }
  }

  cursor = new Date(cursor.getTime() + 30 * 60000);
}

let message = '';

if (slots.length > 0) {
  const slotText = slots.slice(0, 8).map(s => `• ${s.time}`).join('\n');

  message =
`${ctx.query_date_net} tarihi için uygun saatler:

${slotText}

Randevu almak istediğiniz saati yazabilirsiniz.`;
} else {
  message =
`${ctx.query_date_net} tarihinde uygun saat görünmüyor. İsterseniz yarın veya başka bir gün için boş saatleri kontrol edebilirim.`;
}

return [
  {
    json: {
      ...ctx,
      available_slots: slots,
      available_slots_text: slots.map(s => s.time).join(', '),
      final_message: message
    }
  }
];

const ctx = $('Resolve Date and Time').first().json;

function getEventStart(e) {
  return e.start?.dateTime || e.start?.date || e.startDateTime || e.start_date || e.start_time;
}

function getEventEnd(e) {
  return e.end?.dateTime || e.end?.date || e.endDateTime || e.end_date || e.end_time;
}

function overlaps(aStart, aEnd, bStart, bEnd) {
  return aStart < bEnd && aEnd > bStart;
}

const start = new Date(ctx.start_datetime_iso);
const end = new Date(ctx.end_datetime_iso);

let hasConflict = false;
let conflictEvent = null;

const events = $input.all().map(i => i.json);

if (!ctx.start_datetime_iso || !ctx.end_datetime_iso || isNaN(start.getTime()) || isNaN(end.getTime())) {
  return [
    {
      json: {
        ...ctx,
        can_create: false,
        has_conflict: false,
        final_message: 'Randevu oluşturmak için gün ve saat bilgisini net yazmanız gerekiyor. Örneğin: yarın 14:00 saç kesimi.'
      }
    }
  ];
}

for (const event of events) {
  const eventStartRaw = getEventStart(event);
  const eventEndRaw = getEventEnd(event);

  if (!eventStartRaw || !eventEndRaw) continue;

  const eventStart = new Date(eventStartRaw);
  const eventEnd = new Date(eventEndRaw);

  if (isNaN(eventStart.getTime()) || isNaN(eventEnd.getTime())) continue;

  if (overlaps(start, end, eventStart, eventEnd)) {
    hasConflict = true;
    conflictEvent = {
      id: event.id || null,
      summary: event.summary || null,
      start: eventStartRaw,
      end: eventEndRaw
    };
    break;
  }
}

let finalMessage = '';

if (hasConflict) {
  finalMessage = `${ctx.appointment_date_net} ${ctx.appointment_time_net} için başka bir randevu görünüyor. Lütfen farklı bir saat seçin.`;
} else {
  finalMessage = `${ctx.appointment_date_net} ${ctx.appointment_time_net} için randevu oluşturulabilir.`;
}

return [
  {
    json: {
      ...ctx,
      can_create: !hasConflict,
      has_conflict: hasConflict,
      conflict_event: conflictEvent,
      final_message: finalMessage
    }
  }
];
